#!/usr/bin/env python3
from pydantic import BaseModel

class User(BaseModel):
    name: str
    class Config:
        orm_mode = True

try:
    # Try to use from_orm
    user = User.from_orm({"name": "test"})
    print("from_orm worked")
except Exception as e:
    print(f"Error with from_orm: {type(e).__name__}: {e}")

# Try with from_attributes
try:
    class User2(BaseModel):
        name: str
        class Config:
            from_attributes = True

    user2 = User2.from_orm({"name": "test2"})
    print("from_orm with from_attributes worked")
except Exception as e:
    print(f"Error with from_orm and from_attributes: {type(e).__name__}: {e}")

# Try model_validate
try:
    class User3(BaseModel):
        name: str

    user3 = User3.model_validate({"name": "test3"})
    print("model_validate worked")
except Exception as e:
    print(f"Error with model_validate: {type(e).__name__}: {e}")

